package com.example.lending.domain;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;

/**
 * 한 책의 예약 줄. 소진되지 않은 예약만 순서대로 담는다.
 */
public class ReservationQueue {

    private final UUID bookId;
    private final List<Reservation> waiting;

    private ReservationQueue(UUID bookId, List<Reservation> waiting) {
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.waiting = new ArrayList<>(waiting);
    }

    public static ReservationQueue of(UUID bookId, List<Reservation> activeReservations) {
        return new ReservationQueue(bookId, activeReservations);
    }

    /**
     * 줄 맨 뒤에 예약을 세우고 그 순서(1부터 시작)를 돌려준다.
     */
    public int enqueue(Reservation reservation) {
        boolean alreadyReserved = waiting.stream()
                .anyMatch(r -> r.getMemberId().equals(reservation.getMemberId()));
        if (alreadyReserved) {
            throw new AlreadyReservedException(bookId, reservation.getMemberId());
        }
        waiting.add(reservation);
        return waiting.size();
    }

    /**
     * 예약이 없으면 아무 일도 하지 않는다(빈 Optional). 예약이 있으면 맨 앞 예약자만 빌릴 수 있고,
     * 맨 앞 예약자라면 예약을 소진시켜 돌려준다.
     */
    public Optional<Reservation> fulfillFor(UUID memberId) {
        if (waiting.isEmpty()) {
            return Optional.empty();
        }
        Reservation first = waiting.get(0);
        if (!first.getMemberId().equals(memberId)) {
            throw new ReservedForOtherException(bookId);
        }
        first.fulfill();
        waiting.remove(0);
        return Optional.of(first);
    }

    public List<Reservation> waiting() {
        return List.copyOf(waiting);
    }
}

