package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class ReservationIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void reserving_an_available_book_returns_409_with_book_available() throws Exception {
        String bookId = registerBook("Available Book");

        mockMvc.perform(post("/books/{bookId}/reservations", bookId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reserveRequest(registerMember())))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_AVAILABLE"));
    }

    @Test
    void reservations_are_queued_in_order_and_listed_with_positions() throws Exception {
        String bookId = registerBook("Queued Book");
        String holderId = registerMember();
        loanBook(bookId, holderId);
        String firstId = registerMember();
        String secondId = registerMember();

        mockMvc.perform(post("/books/{bookId}/reservations", bookId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reserveRequest(firstId)))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.reservationId").exists())
                .andExpect(jsonPath("$.position").value(1));
        mockMvc.perform(post("/books/{bookId}/reservations", bookId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reserveRequest(secondId)))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(2));

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].memberId").value(firstId))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[1].memberId").value(secondId))
                .andExpect(jsonPath("$[1].position").value(2));
    }

    @Test
    void same_member_cannot_reserve_the_same_book_twice() throws Exception {
        String bookId = registerBook("Double Reserve Book");
        loanBook(bookId, registerMember());
        String memberId = registerMember();
        reserve(bookId, memberId);

        mockMvc.perform(post("/books/{bookId}/reservations", bookId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reserveRequest(memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RESERVED"));
    }

    @Test
    void after_return_only_the_first_reserver_can_loan_and_the_next_becomes_first() throws Exception {
        String bookId = registerBook("Returned Book");
        String holderId = registerMember();
        String loanId = loanBook(bookId, holderId);
        String firstId = registerMember();
        String secondId = registerMember();
        reserve(bookId, firstId);
        reserve(bookId, secondId);

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, secondId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, firstId)))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.memberId").value(firstId));

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].memberId").value(secondId))
                .andExpect(jsonPath("$[0].position").value(1));
    }

    @Test
    void book_without_reservations_can_still_be_loaned_by_anyone() throws Exception {
        String bookId = registerBook("Open Book");
        String loanId = loanBook(bookId, registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, registerMember())))
                .andExpect(status().isCreated());
    }

    @Test
    void reserving_an_unknown_book_returns_404() throws Exception {
        mockMvc.perform(post("/books/{bookId}/reservations", UUID.randomUUID())
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reserveRequest(registerMember())))
                .andExpect(status().isNotFound());
    }

    private void reserve(String bookId, String memberId) throws Exception {
        mockMvc.perform(post("/books/{bookId}/reservations", bookId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reserveRequest(memberId)))
                .andExpect(status().isCreated());
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String loanRequest(String bookId, String memberId) {
        return "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\"}";
    }

    private String reserveRequest(String memberId) {
        return "{\"memberId\":\"" + memberId + "\"}";
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"예약자\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }
}

